const item = $input.first().json.body || $input.first().json;

const postId = item.postId || item.id || 'POST-1';
const authorName = item.authorName || 'Resident';
const flatNumber = item.flatNumber || 'Flat';
const authorRole = item.authorRole || 'RESIDENT';
const title = item.title || '';
const content = item.content || item.summary || '';
const postType = item.type || 'COMMUNITY_UPDATE';

const prompt = `You are the Chief Community Moderator & Civil Discourse Guardian for the Mana Community Association.
Analyze the following community feed post / announcement for hate speech, personal attacks, commercial spam, defamation, or panic rumors.

Post Details:
- Author: ${authorName} (${flatNumber}) [${authorRole}]
- Type: ${postType}
- Title: "${title}"
- Content Body: "${content}"

Community Standards:
1. Zero tolerance for profanity, slurs, threats, or religious/caste discrimination.
2. Civil Discourse: Public naming and shaming of individual neighbors or security guards is strictly prohibited.
3. Defamation: Accusations of corruption or theft must be routed to formal grievance channels, not posted on public feed.
4. Commercial spam / MLM / unapproved sales pitches are disallowed on general discussion feed.
5. Constructive critique of society amenities or management decisions IS permitted if worded respectfully.

Respond ONLY with a valid JSON object matching this schema:
{
  "moderationStatus": "APPROVED" | "NEEDS_REVISION" | "FLAGGED_FOR_MANAGER" | "REJECTED",
  "toxicityScore": number (0.0 to 1.0),
  "sentiment": "POSITIVE" | "NEUTRAL" | "CONSTRUCTIVE_CRITIQUE" | "HOSTILE",
  "isDefamatory": boolean,
  "isSpam": boolean,
  "flaggedViolations": [
    {
      "category": "PROFANITY" | "HARASSMENT" | "SPAM" | "DEFAMATION" | "PANIC_RUMOR",
      "excerpt": string,
      "reason": string
    }
  ],
  "sanitizedContent": string | null,
  "authorFeedback": "Constructive, polite explanation to the resident on whether their post is approved or how to rephrase it to comply with society guidelines."
}`;

return [{
  json: {
    postId,
    authorName,
    flatNumber,
    prompt
  }
}];

const geminiResponse = $input.first().json;
let parsedRuling = {};

try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsedRuling = JSON.parse(rawText);
} catch (err) {
  parsedRuling = {
    moderationStatus: "APPROVED",
    toxicityScore: 0.05,
    sentiment: "NEUTRAL",
    isDefamatory: false,
    isSpam: false,
    flaggedViolations: [],
    sanitizedContent: null,
    authorFeedback: "Post verified and approved for community publication."
  };
}

const meta = $('Prepare Feed Moderation Prompt').first().json;

return [{
  json: {
    status: "success",
    postId: meta.postId,
    moderatedAt: new Date().toISOString(),
    moderation: parsedRuling
  }
}];
